def get_teams(league_code, team_id=None, external_team_id=None, abbreviation=None, city=None, name=None, full_name=None, conference=None, division=None, status=None, limit=None, cursor=None, sort=None, order=None, log_request=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0425000" if __import__("os").path.isdir("./environment_mix/0425000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return "bad"
        try:
            s = c
            pad = "=" * (-len(s) % 4)
            raw = base64.urlsafe_b64decode((s + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "offset" not in obj:
                return "bad"
            off = obj["offset"]
            if not isinstance(off, int) or off < 0:
                return "bad"
            return off
        except Exception:
            return "bad"

    def _make_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _log(http_status, league_code_ctx=None, game_id_ctx=None):
        if log_request is False:
            return
        logs = _load("api_request_logs.json")
        resp_ms = int(max(0, round((time.time() - t0) * 1000)))
        log_row = {
            "id": "bdl_log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "request_time": now,
            "tool_name": "get_teams",
            "league_code": league_code_ctx,
            "game_id": game_id_ctx,
            "http_status": int(http_status),
            "response_ms": int(resp_ms),
            "client_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(log_row)
        _save("api_request_logs.json", logs)

    # Validate
    if league_code not in ("NBA", "MLB", "NFL"):
        _log(400, None, None)
        return _err("VALIDATION_ERROR", "league_code must be one of: NBA, MLB, NFL", field="league_code")

    id_pat = re.compile(r"^bdl_tm_01H[0-9A-Z]{15,}$")
    if team_id is not None and (not isinstance(team_id, str) or not id_pat.match(team_id)):
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "team_id is invalid", field="team_id")
    if status is not None and status not in ("active", "inactive", "relocated"):
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive, relocated", field="status")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    if sort is None:
        sort = "name"
    if sort not in ("created_at", "updated_at", "name", "full_name", "abbreviation", "city"):
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'", field="order")

    offset = _parse_cursor(cursor)
    if offset == "bad":
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
    if offset is None:
        offset = 0

    # Load data
    leagues = _load("leagues.json")
    teams = _load("teams.json")

    league = next((l for l in leagues if isinstance(l, dict) and l.get("code") == league_code), None)
    if not league or league.get("status") != "active":
        # read with filters match nothing => empty set
        _log(200, league_code, None)
        return {
            "data": [],
            "meta": {"total": 0, "has_more": False, "next_cursor": None},
        }

    league_id = league.get("id")

    # Business rule baseline filter: teams.status='active' and league.status='active'
    rows = []
    for tm in teams:
        if not isinstance(tm, dict):
            continue
        if tm.get("league_id") != league_id:
            continue
        if tm.get("status") != "active":
            continue

        # Optional filters (including explicit status filter; cannot override baseline active rule)
        if team_id is not None and tm.get("id") != team_id:
            continue
        if external_team_id is not None and tm.get("external_team_id") != external_team_id:
            continue
        if abbreviation is not None and tm.get("abbreviation") != abbreviation:
            continue
        if city is not None and tm.get("city") != city:
            continue
        if name is not None and tm.get("name") != name:
            continue
        if full_name is not None and tm.get("full_name") != full_name:
            continue
        if conference is not None and tm.get("conference") != conference:
            continue
        if division is not None and tm.get("division") != division:
            continue
        if status is not None and tm.get("status") != status:
            continue

        rows.append(tm)

    def _sort_key(r):
        v = r.get(sort)
        return (v is None, v)

    rows.sort(key=_sort_key, reverse=(order == "desc"))
    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _log(200, league_code, None)
    return {
        "data": page,
        "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor},
    }

