def get_games(league_code, season=None, team_id=None, home_team_id=None, away_team_id=None, status=None, start_time_from=None, start_time_to=None, limit=None, cursor=None, sort=None, order=None, log_request=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0425000" if __import__("os").path.isdir("./environment_mix/0425000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return "bad"
        try:
            x = s
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return "bad"

    def _parse_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return "bad"
        try:
            pad = "=" * (-len(c) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return "bad"
            return off
        except Exception:
            return "bad"

    def _make_cursor(off):
        raw = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    def _log(http_status, league_code_ctx=None, game_id_ctx=None):
        if log_request is False:
            return
        logs = _load("api_request_logs.json")
        resp_ms = int(max(0, round((time.time() - t0) * 1000)))
        logs.append({
            "id": "bdl_log_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "request_time": now,
            "tool_name": "get_games",
            "league_code": league_code_ctx,
            "game_id": game_id_ctx,
            "http_status": int(http_status),
            "response_ms": int(resp_ms),
            "client_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("api_request_logs.json", logs)

    # Validate
    if league_code not in ("NBA", "MLB", "NFL"):
        _log(400, None, None)
        return _err("VALIDATION_ERROR", "league_code must be one of: NBA, MLB, NFL", field="league_code")

    tid_pat = re.compile(r"^bdl_tm_01H[0-9A-Z]{15,}$")
    for fld, val in (("team_id", team_id), ("home_team_id", home_team_id), ("away_team_id", away_team_id)):
        if val is not None and (not isinstance(val, str) or not tid_pat.match(val)):
            _log(400, league_code, None)
            return _err("VALIDATION_ERROR", f"{fld} is invalid", field=fld)

    if season is not None:
        if not isinstance(season, int):
            _log(400, league_code, None)
            return _err("VALIDATION_ERROR", "season must be an integer", field="season")
        if season < 1800 or season > 2200:
            _log(400, league_code, None)
            return _err("VALIDATION_ERROR", "season must be between 1800 and 2200", field="season")

    if status is not None and status not in ("scheduled", "in_progress", "final", "cancelled", "postponed"):
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "status is invalid", field="status")

    dt_from = _parse_dt(start_time_from, "start_time_from")
    if dt_from == "bad":
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "start_time_from must be RFC3339 date-time", field="start_time_from")
    dt_to = _parse_dt(start_time_to, "start_time_to")
    if dt_to == "bad":
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "start_time_to must be RFC3339 date-time", field="start_time_to")
    if isinstance(dt_from, datetime.datetime) and isinstance(dt_to, datetime.datetime) and dt_from > dt_to:
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "start_time_from must be <= start_time_to", field="start_time_from")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")

    if sort is None:
        sort = "start_time"
    if sort not in ("start_time", "created_at", "updated_at", "season"):
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "sort is invalid", field="sort")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "order must be 'asc' or 'desc'", field="order")

    offset = _parse_cursor(cursor)
    if offset == "bad":
        _log(400, league_code, None)
        return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")
    if offset is None:
        offset = 0

    leagues = _load("leagues.json")
    teams = _load("teams.json")
    games = _load("games.json")

    league = next((l for l in leagues if isinstance(l, dict) and l.get("code") == league_code), None)
    if not league or league.get("status") != "active":
        _log(200, league_code, None)
        return {"data": [], "meta": {"total": 0, "has_more": False, "next_cursor": None}}

    league_id = league.get("id")
    teams_by_id = {t.get("id"): t for t in teams if isinstance(t, dict) and t.get("id")}

    def _game_start_dt(g):
        st = g.get("start_time")
        if not st:
            return None
        try:
            x = st
            if isinstance(x, str) and x.endswith("Z"):
                x = x[:-1] + "+00:00"
            if isinstance(x, str):
                return datetime.datetime.fromisoformat(x)
        except Exception:
            return None
        return None

    rows = []
    for g in games:
        if not isinstance(g, dict):
            continue
        if g.get("league_id") != league_id:
            continue

        # Business rule: home/away must reference teams in same league
        ht = teams_by_id.get(g.get("home_team_id"))
        at = teams_by_id.get(g.get("away_team_id"))
        if not ht or not at:
            continue
        if ht.get("league_id") != league_id or at.get("league_id") != league_id:
            continue

        # Optional filters
        if season is not None and g.get("season") != season:
            continue
        if status is not None and g.get("status") != status:
            continue
        if team_id is not None and not (g.get("home_team_id") == team_id or g.get("away_team_id") == team_id):
            continue
        if home_team_id is not None and g.get("home_team_id") != home_team_id:
            continue
        if away_team_id is not None and g.get("away_team_id") != away_team_id:
            continue

        if dt_from is not None or dt_to is not None:
            gst = _game_start_dt(g)
            if gst is None:
                continue
            if dt_from is not None and gst < dt_from:
                continue
            if dt_to is not None and gst > dt_to:
                continue

        rows.append(g)

    def _sort_key(r):
        if sort == "start_time":
            v = _game_start_dt(r)
            return (v is None, v)
        v = r.get(sort)
        return (v is None, v)

    rows.sort(key=_sort_key, reverse=(order == "desc"))
    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    _log(200, league_code, None)
    return {"data": page, "meta": {"total": total, "has_more": has_more, "next_cursor": next_cursor}}

def get_game(league_code, game_id=None, external_game_id=None, log_request=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0425000" if __import__("os").path.isdir("./environment_mix/0425000") else "/app/database")

