    def _new_log_id(existing):
        # Match datastore's id prefix convention bdl_rql_
        return "bdl_rql_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f") + "_" + str(len(existing) + 1)

    def _log(http_status, league_code_ctx=None, game_id_ctx=None):
        if log_request is False:
            return
        logs = _load("api_request_logs.json")
        if not isinstance(logs, list):
            logs = []
        resp_ms = int(max(0, round((time.time() - t0) * 1000)))
        row = {
            "id": _new_log_id(logs),
            "request_time": now,
            "tool_name": "get_game",
            "league_code": league_code_ctx,
            "game_id": game_id_ctx,
            "http_status": int(http_status),
            "response_ms": int(resp_ms),
            "client_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("api_request_logs.json", logs)

    # ---- validation (relaxed to accept well-formed strings even if they don't match the internal-id pattern) ----
    if not isinstance(league_code, str) or league_code not in ("NBA", "MLB", "NFL"):
        _log(400, None, game_id or external_game_id)
        return _err("VALIDATION_ERROR", "league_code must be one of: NBA, MLB, NFL", field="league_code")

    if log_request is not None and not isinstance(log_request, bool):
        _log(400, league_code, game_id or external_game_id)
        return _err("VALIDATION_ERROR", "log_request must be a boolean", field="log_request")

    if game_id is None and external_game_id is None:
        _log(400, league_code, None)
