        for g in games:
            if not isinstance(g, dict):
                continue
            if g.get("league_id") != league_id:
                continue
            if g.get("id") == game_id:
                match = g
                break
        if match is None:
            for g in games:
                if not isinstance(g, dict):
                    continue
                if g.get("league_id") != league_id:
                    continue
                if g.get("external_game_id") == game_id:
                    match = g
                    break

    if match is None and external_game_id is not None:
