        rows.append(lg)

    # Sort
    reverse = (order == "desc")
    def _sort_key(x):
        v = x.get(sort)
        return (v is None, v)
    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except TypeError:
        # If mixed types exist, fall back to string compare for determinism
        rows.sort(key=lambda x: str(x.get(sort)), reverse=reverse)

    total = len(rows)

    # Cursor pagination: cursor encodes an integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                _log(400, league_code=code)
                return _err("VALIDATION_ERROR", "cursor is invalid.")
            offset = int(s.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            _log(400, league_code=code)
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    _log(200, league_code=code)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": next_cursor,
            "has_more": has_more,
        },
    }

