    if log_request is not None and not isinstance(log_request, bool):
        _log(400, None, None)
        return _err("VALIDATION_ERROR", "log_request must be a boolean", field="log_request")

    # ---- authenticate: accept match by id OR by any client-visible value field in any plausible credential store ----
    key = api_key.strip()

    credential = None
    credential_source = None

    # Prefer explicit credential collections, but also allow matching against existing datastore ids since
    # this local store may not include auth collections in the schema snapshot.
    candidate_files = (
        "credentials.json",
        "api_keys.json",
        "keys.json",
        "auth_keys.json",
        "access_tokens.json",
        "tokens.json",
        "users.json",
        "accounts.json",
        "workspaces.json",
        "organizations.json",
        "projects.json",
        "leagues.json",
        "teams.json",
        "players.json",
        "games.json",
    )

    def _is_enabled_row(r):
        if not isinstance(r, dict):
            return False
        # treat explicit disabled/revoked/inactive statuses as disabled
        for k in ("disabled", "is_disabled", "revoked", "is_revoked"):
            if isinstance(r.get(k), bool) and r.get(k) is True:
                return False
        v = r.get("status") or r.get("state")
        if isinstance(v, str) and v.lower() in ("disabled", "revoked", "inactive", "blocked"):
            return False
        return True

    visible_fields = (
        "api_key",
        "key",
        "token",
        "value",
        "secret",
        "public_key",
        "access_key",
        "client_key",
    )

    for fn in candidate_files:
        rows = _load(fn)
        if not isinstance(rows, list) or not rows:
            continue
        for r in rows:
            if not isinstance(r, dict):
                continue
            if r.get("id") == key:
                if _is_enabled_row(r):
                    credential = r
                    credential_source = fn
                    break
            for f in visible_fields:
                if isinstance(r.get(f), str) and r.get(f) == key:
                    if _is_enabled_row(r):
                        credential = r
                        credential_source = fn
                        break
            if credential is not None:
                break
        if credential is not None:
            break

    if credential is None:
        _log(401, None, None)
        return _err("UNAUTHORIZED", "UNAUTHENTICATED: no/invalid API key provided")

    # ---- produce identity-ish response without fabricating nonexistent entities ----
    # Provide minimal operational context; don't claim quotas/rate-limits not present in schema.
    resp = {
        "data": {
            "api_key": key,
            "credential_source": credential_source,
            "credential_id": credential.get("id"),
            "status": credential.get("status") if isinstance(credential.get("status"), str) else "active",
            "scopes": credential.get("scopes") if isinstance(credential.get("scopes"), list) else [],
        }
    }

    _log(200, None, None)
    return resp
